import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Reading Data in AL","description":"","frontmatter":{},"headers":[],"relativePath":"records-data-access-filtering-and-validation/reading-data.md","filePath":"records-data-access-filtering-and-validation/reading-data.md"}`),a={name:`records-data-access-filtering-and-validation/reading-data.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="reading-data-in-al" tabindex="-1">Reading Data in AL <a class="header-anchor" href="#reading-data-in-al" aria-label="Permalink to “Reading Data in AL”">​</a></h1><p>AL provides several methods for retrieving records from Business Central tables. The most commonly used are <code>Get()</code>, <code>FindFirst()</code>, <code>FindLast()</code>, <code>FindSet()</code>, and <code>Next()</code>.</p><h2 id="_1-get" tabindex="-1">1. Get() <a class="header-anchor" href="#_1-get" aria-label="Permalink to “1. Get()”">​</a></h2><p><code>Get()</code> retrieves a <strong>specific record using its primary key</strong>.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if ProductRec.Get(&#39;PROD001&#39;) then</span></span>
<span class="line"><span>        Message(&#39;Product: %1&#39;, ProductRec.Name)</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        Message(&#39;Product not found.&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Key points:</p><ul><li>Retrieves a record using its primary key.</li><li>Returns <code>true</code> if the record exists and <code>false</code> otherwise.</li><li>Can accept multiple arguments when the table has a composite primary key.</li><li>Does not use ordinary filters applied through <code>SetRange()</code> or <code>SetFilter()</code> to locate the record.</li></ul><p><strong>Use it when you know the primary key of the record you want.</strong></p><h2 id="_2-findfirst" tabindex="-1">2. FindFirst() <a class="header-anchor" href="#_2-findfirst" aria-label="Permalink to “2. FindFirst()”">​</a></h2><p><code>FindFirst()</code> retrieves the first record matching the current filters and sorting order.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if ProductRec.FindFirst() then</span></span>
<span class="line"><span>        Message(&#39;First product: %1&#39;, ProductRec.Name)</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        Message(&#39;No products found.&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Key points:</p><ul><li>Respects filters applied to the record variable.</li><li>Uses the current key and sort order.</li><li>Returns <code>true</code> if a matching record is found.</li></ul><p><strong>Use it when you need the first record in a filtered result set.</strong></p><h2 id="_3-findlast" tabindex="-1">3. FindLast() <a class="header-anchor" href="#_3-findlast" aria-label="Permalink to “3. FindLast()”">​</a></h2><p><code>FindLast()</code> retrieves the last record matching the current filters and sorting order.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if ProductRec.FindLast() then</span></span>
<span class="line"><span>        Message(&#39;Last product: %1&#39;, ProductRec.Name)</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        Message(&#39;No products found.&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Key points:</p><ul><li>Respects current filters and sorting.</li><li>Returns <code>true</code> if a matching record is found.</li></ul><p><strong>Use it when you need the last record in a filtered result set.</strong></p><h2 id="_4-findset" tabindex="-1">4. FindSet() <a class="header-anchor" href="#_4-findset" aria-label="Permalink to “4. FindSet()”">​</a></h2><p><code>FindSet()</code> retrieves a set of records matching the current filters.</p><p>It is particularly useful when you want to iterate through multiple records.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if ProductRec.FindSet() then</span></span>
<span class="line"><span>        repeat</span></span>
<span class="line"><span>            Message(&#39;Product: %1&#39;, ProductRec.Name);</span></span>
<span class="line"><span>        until ProductRec.Next() = 0;</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Key points:</p><ul><li>Retrieves the complete filtered set of records.</li><li>Returns <code>true</code> if records are found.</li><li>Commonly used with <code>Next()</code> to iterate through records.</li><li>Can accept a Boolean parameter, <code>ForUpdate</code>, when you intend to modify or delete records in the result set.</li></ul><p>Example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if ProductRec.FindSet(true) then</span></span>
<span class="line"><span>    repeat</span></span>
<span class="line"><span>        ProductRec.Inventory += 1;</span></span>
<span class="line"><span>        ProductRec.Modify();</span></span>
<span class="line"><span>    until ProductRec.Next() = 0;</span></span></code></pre></div><p><strong>Use it when you intend to process all records matching your filters.</strong></p><h2 id="_5-next" tabindex="-1">5. Next() <a class="header-anchor" href="#_5-next" aria-label="Permalink to “5. Next()”">​</a></h2><p><code>Next()</code> moves the record variable to the next or previous record in the current result set.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Next();</span></span></code></pre></div><p>By default, it moves forward by one record.</p><p>It returns:</p><ul><li><code>1</code> when it successfully moves one record forward.</li><li><code>0</code> when it cannot move any further.</li><li>A negative number when moving backwards.</li></ul><p>You can also specify how many records to move:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Next(3);</span></span></code></pre></div><p>This attempts to move three records forward.</p><p><code>Next()</code> is commonly used with <code>FindSet()</code> when iterating through records.</p><h2 id="_6-iterating-through-records" tabindex="-1">6. Iterating Through Records <a class="header-anchor" href="#_6-iterating-through-records" aria-label="Permalink to “6. Iterating Through Records”">​</a></h2><p>Iteration means going through a collection of records one at a time and performing an operation on each record.</p><p>In AL, the common pattern is:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if ProductRec.FindSet() then</span></span>
<span class="line"><span>    repeat</span></span>
<span class="line"><span>        // Process current record.</span></span>
<span class="line"><span>    until ProductRec.Next() = 0;</span></span></code></pre></div><p>Let&#39;s look at a practical example.</p><h3 id="example-display-all-products" tabindex="-1">Example: Display all products <a class="header-anchor" href="#example-display-all-products" aria-label="Permalink to “Example: Display all products”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 ProductManager</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnRun()</span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        ProductRec: Record Product;</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        if ProductRec.FindSet() then</span></span>
<span class="line"><span>            repeat</span></span>
<span class="line"><span>                Message(</span></span>
<span class="line"><span>                    &#39;Product: %1 | Inventory: %2&#39;,</span></span>
<span class="line"><span>                    ProductRec.Name,</span></span>
<span class="line"><span>                    ProductRec.Inventory</span></span>
<span class="line"><span>                );</span></span>
<span class="line"><span>            until ProductRec.Next() = 0;</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>What happens?</p><ol><li><code>FindSet()</code> retrieves the matching products.</li><li>AL processes the current product.</li><li><code>Next()</code> moves to the next product.</li><li>The loop continues until <code>Next()</code> returns <code>0</code>.</li></ol><h2 id="_7-quick-comparison" tabindex="-1">7. Quick Comparison <a class="header-anchor" href="#_7-quick-comparison" aria-label="Permalink to “7. Quick Comparison”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Purpose</th><th>Typical use</th></tr></thead><tbody><tr><td><code>Get()</code></td><td>Retrieves a specific record using its primary key.</td><td>Finding a customer by customer number.</td></tr><tr><td><code>FindFirst()</code></td><td>Retrieves the first matching record.</td><td>Getting the first product.</td></tr><tr><td><code>FindLast()</code></td><td>Retrieves the last matching record.</td><td>Getting the last product.</td></tr><tr><td><code>FindSet()</code></td><td>Retrieves a complete matching set.</td><td>Processing multiple products.</td></tr><tr><td><code>Next()</code></td><td>Moves through records.</td><td>Iterating through a result set.</td></tr></tbody></table><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li><code>Get()</code> is for retrieving a specific record using its primary key.</li><li><code>FindFirst()</code> and <code>FindLast()</code> retrieve the first and last matching records.</li><li><code>FindSet()</code> is commonly used when processing multiple records.</li><li><code>Next()</code> moves through the result set.</li><li>Always check the Boolean result of <code>Get()</code>, <code>FindFirst()</code>, <code>FindLast()</code>, or <code>FindSet()</code> before accessing the retrieved record.</li><li>The common iteration pattern is <code>FindSet()</code> followed by <code>repeat ... until Next() = 0</code>.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-get-method" target="_blank" rel="noreferrer">Record.Get()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-findfirst-method" target="_blank" rel="noreferrer">Record.FindFirst()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-findlast-method" target="_blank" rel="noreferrer">Record.FindLast()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-findset-method" target="_blank" rel="noreferrer">Record.FindSet()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-next-method" target="_blank" rel="noreferrer">Record.Next()</a></li></ul>`,54)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};